mapper.insert:
insert into ws_code
    (CODE_ID
    , CODE_DC
    , CODE_VALUE
    , CODE_NM
    , SORT_ORD
    , USE_YN)
values ( #{codeId}
       , #{codeDc}
       , #{codeValue}
       , #{codeNm}
       , #{sortOrd}
       , #{useYn})

mapper.select:
SELECT DISTINCT CODE_NM, CODE_VALUE
FROM ws_code
WHERE CODE_ID = #{codeId}

mapper.update:
UPDATE ws_code
   SET CODE_ID = #{codeId}
   , CODE_DC = #{codeDc}
   , CODE_NM = #{codeNm}
   , CODE_VALUE = #{codeValue}
   , SORT_ORD = #{sortOrd}
   , USE_YN = #{useYn}
WHERE CODE_SEQ = #{codeSeq}
